-- TrustVault schema (postgres). Generated by `python -m trustvault export-schema`.
-- The application creates this automatically with `python -m trustvault init-db`.

CREATE TABLE audit_checkpoints (
	seq INTEGER NOT NULL, 
	entry_hash VARCHAR(64) NOT NULL, 
	created_at VARCHAR(32) NOT NULL, 
	PRIMARY KEY (seq)
);


CREATE TABLE audit_events (
	seq INTEGER NOT NULL, 
	event_id VARCHAR(36) NOT NULL, 
	occurred_at VARCHAR(32) NOT NULL, 
	actor_id VARCHAR(36), 
	actor_username VARCHAR(64) NOT NULL, 
	actor_role VARCHAR(10), 
	action VARCHAR(48) NOT NULL, 
	outcome VARCHAR(8) NOT NULL, 
	document_id VARCHAR(64), 
	target_user_id VARCHAR(36), 
	ip VARCHAR(64), 
	request_id VARCHAR(36), 
	details TEXT NOT NULL, 
	prev_hash VARCHAR(64) NOT NULL, 
	entry_hash VARCHAR(64) NOT NULL, 
	PRIMARY KEY (seq), 
	CONSTRAINT ck_audit_outcome CHECK (outcome IN ('success','denied','error')), 
	UNIQUE (event_id), 
	UNIQUE (entry_hash)
);

CREATE INDEX ix_audit_action_ip_time ON audit_events (action, ip, occurred_at);
CREATE INDEX ix_audit_actor_time ON audit_events (actor_id, occurred_at);
CREATE INDEX ix_audit_doc ON audit_events (document_id);
CREATE INDEX ix_audit_time ON audit_events (occurred_at);

CREATE TABLE blobs (
	id VARCHAR(36) NOT NULL, 
	ciphertext BYTEA NOT NULL, 
	PRIMARY KEY (id)
);


CREATE TABLE users (
	id VARCHAR(36) NOT NULL, 
	username VARCHAR(32) NOT NULL, 
	display_name VARCHAR(80) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	must_change_password BOOLEAN NOT NULL, 
	is_demo_account BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_users_role CHECK (role IN ('admin','owner','viewer')), 
	UNIQUE (username)
);


CREATE TABLE documents (
	id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(36) NOT NULL, 
	title VARCHAR(160) NOT NULL, 
	category VARCHAR(60) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	deleted_by VARCHAR(36), 
	is_demo_seed BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id)
);

CREATE INDEX ix_documents_category ON documents (category);
CREATE INDEX ix_documents_created_at ON documents (created_at);
CREATE INDEX ix_documents_deleted_at ON documents (deleted_at);
CREATE INDEX ix_documents_owner_id ON documents (owner_id);

CREATE TABLE sessions (
	token_hash VARCHAR(64) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	csrf_token VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	ip VARCHAR(64), 
	user_agent VARCHAR(200), 
	PRIMARY KEY (token_hash), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_sessions_user_id ON sessions (user_id);

CREATE TABLE document_versions (
	id VARCHAR(36) NOT NULL, 
	document_id VARCHAR(36) NOT NULL, 
	version_no INTEGER NOT NULL, 
	original_filename VARCHAR(160) NOT NULL, 
	content_type VARCHAR(100) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	wrapped_key BYTEA NOT NULL, 
	key_id VARCHAR(16) NOT NULL, 
	blob_id VARCHAR(36) NOT NULL, 
	uploaded_by VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_version_no UNIQUE (document_id, version_no), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, 
	UNIQUE (blob_id), 
	FOREIGN KEY(blob_id) REFERENCES blobs (id), 
	FOREIGN KEY(uploaded_by) REFERENCES users (id)
);


CREATE TABLE grants (
	id VARCHAR(36) NOT NULL, 
	document_id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	permission VARCHAR(8) NOT NULL, 
	granted_by VARCHAR(36) NOT NULL, 
	source VARCHAR(12) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_grant_doc_user UNIQUE (document_id, user_id), 
	CONSTRAINT ck_grant_permission CHECK (permission IN ('read','edit')), 
	CONSTRAINT ck_grant_source CHECK (source IN ('manual','suggestion')), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(granted_by) REFERENCES users (id)
);

CREATE INDEX ix_grants_user_doc ON grants (user_id, document_id);

-- Append-only protection for the audit trail
CREATE OR REPLACE FUNCTION tv_append_only() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS audit_events_append_only ON audit_events;
CREATE TRIGGER audit_events_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION tv_append_only();
DROP TRIGGER IF EXISTS audit_events_no_truncate ON audit_events;
CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events FOR EACH STATEMENT EXECUTE FUNCTION tv_append_only();
DROP TRIGGER IF EXISTS audit_checkpoints_append_only ON audit_checkpoints;
CREATE TRIGGER audit_checkpoints_append_only BEFORE UPDATE OR DELETE ON audit_checkpoints FOR EACH ROW EXECUTE FUNCTION tv_append_only();
DROP TRIGGER IF EXISTS audit_checkpoints_no_truncate ON audit_checkpoints;
CREATE TRIGGER audit_checkpoints_no_truncate BEFORE TRUNCATE ON audit_checkpoints FOR EACH STATEMENT EXECUTE FUNCTION tv_append_only();
